macro_rules! deps {
    () => {
        Trait!();
        Macro!();
        Adt!();
        Variant!();
        Enum!();
        VariantDef!();
        Union!();
        Struct!();
        Impl!();
        Crate!();
        Function!();
        Const!();
        Static!();
        Module!();
        Semantics!();
        TypeAlias!();
    };
}

